# -*- coding: utf-8 -*-
# Ngân hàng câu hỏi vấn đáp BrewLite. Mỗi chương: (tiêu đề, mô tả, [ảnh], [(câu hỏi, gợi ý trả lời, mức)])
# mức: 1 cơ bản, 2 hiểu sâu, 3 nâng cao/bẫy.  `code` -> texttt.

CH = []
def ch(title, intro, imgs, qs): CH.append((title, intro, imgs, qs))

ch("Agile, Scrum và quy trình làm việc", "Lý thuyết Scrum và cách đồ án áp dụng ở Assignment 1 (3 Sprint, 10 task) và Assignment 2 (2 Sprint, 5 task).", ["a1/scrum.png"], [
("Agile là gì? Tuyên ngôn Agile gồm những giá trị nào?", "Agile là cách phát triển theo vòng lặp ngắn, giao phần mềm chạy được sớm, nhận phản hồi rồi điều chỉnh. 4 giá trị: con người và tương tác hơn quy trình và công cụ; phần mềm chạy được hơn tài liệu đầy đủ; hợp tác với khách hàng hơn đàm phán hợp đồng; phản hồi thay đổi hơn bám theo kế hoạch. Vế phải vẫn có giá trị, chỉ là vế trái được ưu tiên hơn.", 1),
("Scrum có những vai trò, sự kiện và tạo phẩm nào?", "3 vai trò: Product Owner, Scrum Master, Development Team. 5 sự kiện: Sprint, Sprint Planning, Daily Scrum (15 phút), Sprint Review, Sprint Retrospective. 3 tạo phẩm: Product Backlog, Sprint Backlog, Increment.", 1),
("Product Owner và Scrum Master khác nhau thế nào?", "PO quyết định làm gì và thứ tự ưu tiên (quản lý Product Backlog, nghiệm thu). SM bảo vệ quy trình: điều phối sự kiện, gỡ vướng mắc, giúp nhóm áp dụng Scrum đúng. PO trả lời 'làm cái gì', SM giúp 'làm thế nào cho đúng quy trình'.", 1),
("Sprint Review khác Sprint Retrospective ra sao?", "Review nhìn vào SẢN PHẨM: demo Increment cho PO/khách hàng, nhận phản hồi, cập nhật backlog. Retrospective nhìn vào QUY TRÌNH: nhóm tự hỏi điều gì làm tốt, điều gì cần cải thiện và chọn hành động cho Sprint sau.", 1),
("Em làm một mình thì áp dụng Scrum thế nào?", "Em kiêm cả PO, SM và Developer. Vẫn giữ đủ sự kiện ở quy mô cá nhân: lập kế hoạch đầu Sprint, cập nhật tiến độ hằng ngày (burndown), demo cuối Sprint, viết retrospective. Backlog có ưu tiên và story point; Definition of Done dùng để quyết định task đã xong chưa.", 2),
("Story point là gì? Vì sao không ước lượng bằng giờ?", "Story point đo độ lớn tương đối (độ phức tạp, khối lượng, rủi ro) của một hạng mục, thường dùng dãy Fibonacci. Ước lượng tương đối nhanh và ổn định hơn ước lượng giờ, vì con người so sánh 'cái này to gấp đôi cái kia' tốt hơn đoán chính xác thời gian.", 1),
("Velocity và burndown chart dùng để làm gì?", "Velocity là số story point hoàn thành mỗi Sprint, dùng để dự báo Sprint sau nhận được bao nhiêu việc. Burndown chart vẽ story point còn lại theo ngày; so đường thực tế với đường lý tưởng để biết đang chậm hay nhanh.", 1),
("Definition of Done của đồ án gồm những gì?", "A1: code chạy không lỗi build, có commit rõ ràng, API validate và UI xử lý loading/lỗi, có README. A2 mở rộng thành 8 điểm: merge qua PR theo mẫu; CI xanh (lint, unit, build, integration, e2e, quét secret); có test cho hành vi mới; validate backend + loading/rỗng/lỗi frontend; đổi schema có migration kèm down(); tài liệu cập nhật cùng PR; không lộ secret; CD triển khai và smoke test đạt.", 2),
("Definition of Done khác Acceptance Criteria thế nào?", "Acceptance Criteria gắn với TỪNG user story (story này cần đạt điều kiện gì). Definition of Done áp dụng CHUNG cho mọi hạng mục (chất lượng tối thiểu: test, review, tài liệu, triển khai). Một story chỉ Done khi đạt cả hai.", 2),
("Assignment 1 chia Sprint thế nào?", "3 Sprint, mỗi Sprint 10 ngày, 10 task, tổng 33 SP. Sprint 1: Task 1–4 (khởi tạo, API sản phẩm, menu, chi tiết) = 10 SP. Sprint 2: Task 5–7 (giỏ, API đơn, JWT) = 9 SP. Sprint 3: Task 8–10 (thanh toán, xác nhận/lịch sử/Docker, nghiệp vụ backend) = 14 SP vì Task 10 chiếm 8 SP.", 1),
("Assignment 2 chia Sprint thế nào?", "2 Sprint. Sprint 1 (27 SP, 11 hạng mục): tài liệu Task 1–3, repo, quy ước, CI, MVP xem menu. Sprint 2 (32 SP, 13 hạng mục): hoàn thiện MVP, migration, health, PWA, E2E, CD, triển khai production, bàn giao.", 1),
("Sprint Goal là gì? Cho ví dụ trong đồ án.", "Một câu nêu mục tiêu của Sprint, giúp nhóm ra quyết định khi phát sinh. Sprint 1 A2: 'Tạo nền tảng kỹ thuật, tài liệu có kiểm soát phiên bản và MVP đầu tiên chạy được cho luồng xem menu'. Sprint 2 A2: 'Hoàn thành luồng end-to-end, tự động hóa đóng gói và triển khai một phiên bản production'.", 1),
("Vì sao đề A2 yêu cầu làm 5 task tuần tự?", "Để mô phỏng đúng vòng đời: yêu cầu phải có trước mới mô hình hóa, mô hình có trước mới thiết kế kiến trúc, rồi mới code. Task sau chỉ được nghiệm thu khi tạo phẩm task trước đã có trên repo với lịch sử rõ ràng; vì vậy git của em có các commit docs(task1) → docs(task2) → docs(task3) → chore(task4) → feat(task5).", 2),
("MVP là gì? MVP khác prototype/mockup thế nào?", "MVP (Minimum Viable Product) là phiên bản nhỏ nhất CHẠY ĐƯỢC, đủ tính năng cốt lõi để kiểm chứng giả thuyết với người dùng thật. Mockup chỉ là hình tĩnh; prototype có thể bấm thử nhưng thường không có backend thật.", 1),
("Nếu PO đổi yêu cầu giữa Sprint thì em xử lý thế nào?", "Không đưa thẳng vào Sprint đang chạy nếu làm lệch Sprint Goal: ghi vào Product Backlog, PO ưu tiên lại, đưa vào Sprint sau. Nếu thay đổi khẩn cấp làm Sprint Goal mất ý nghĩa thì PO có thể hủy Sprint và lập kế hoạch lại. Tài liệu yêu cầu đổi qua pull request có ghi lý do.", 3),
])

ch("Khai thác và đặc tả yêu cầu", "Stakeholder, phạm vi, FR/NFR, user story, tiêu chí chấp nhận, MoSCoW, đặc tả UC-05 (Task 1 của A2).", [], [
("Product Vision của BrewLite là gì?", "'BrewLite giúp khách hàng đặt và thanh toán đồ uống không dùng tiền mặt chỉ trong vài chạm, giảm thời gian xếp hàng và nhận đơn nhanh tại quầy.'", 1),
("Vấn đề nghiệp vụ mà BrewLite giải quyết?", "Giờ cao điểm hàng dài trước quầy, khách mất 1–3 phút gọi món và trả tiền nên bỏ về; nhân viên vừa nhận order vừa thu tiền dễ nhầm món/size/topping; quán không có dữ liệu đơn và chương trình khách hàng thân thiết.", 1),
("Stakeholder là gì? Kể các stakeholder của đồ án.", "Stakeholder là người hoặc tổ chức bị ảnh hưởng hoặc có ảnh hưởng tới hệ thống. 6 nhóm: khách hàng, nhân viên quầy, quản lý cửa hàng, giảng viên/khách hàng nghiệm thu, nhóm phát triển, đơn vị thanh toán. Mỗi nhóm có mục tiêu và kỳ vọng riêng (ví dụ khách muốn không bị trừ tiền hai lần, quản lý muốn không bán vượt kho).", 1),
("Phạm vi in-scope, mở rộng và out-of-scope khác nhau thế nào?", "In-scope: làm trong MVP (FR-01..FR-13, health, CI/CD). Mở rộng: chưa làm bản này nhưng có trong backlog (giao diện nhân viên, cổng thật, thông báo READY, đơn tự hết hạn). Out-of-scope: không làm trong dự án (giao hàng, tiền mặt, nhiều chi nhánh, app native, kế toán, lưu thẻ).", 1),
("Giả định và ràng buộc khác nhau ra sao? Cho ví dụ.", "Giả định là điều coi là đúng nhưng chưa kiểm chứng, nếu sai thì phải xem lại thiết kế (A-01 khách có smartphone và Internet; A-03 cổng mô phỏng hành xử như cổng thật). Ràng buộc là điều bắt buộc phải tuân theo (C-01 bắt buộc Next.js, NestJS, PostgreSQL; C-03 ngân sách 0 đồng; C-05 secret không vào repo).", 2),
("Kể các rủi ro ban đầu và biện pháp.", "R-01 trừ tiền hai lần → Idempotency-Key, UNIQUE, khóa dòng. R-02 bán vượt kho → optimistic lock, CHECK stock >= 0. R-03 một người làm dễ trễ → MoSCoW, tự động hóa. R-04 gói miễn phí Render ngủ/Postgres hết hạn → smoke test thử lại, mở URL trước giờ chấm. R-05 lộ secret → .gitignore, gitleaks. R-06 migration lỗi → 1 transaction, health check. R-07 lệch giá → server tính lại, hỏi khách.", 2),
("Yêu cầu chức năng và phi chức năng khác nhau thế nào?", "FR mô tả hệ thống LÀM GÌ (xem menu, đặt đơn, thanh toán). NFR mô tả hệ thống làm TỐT ĐẾN ĐÂU (hiệu năng < 500 ms, bảo mật bcrypt/JWT, khả dụng trên di động, khả năng triển khai).", 1),
("SRS của em có bao nhiêu FR, NFR? Kể vài cái.", "FR-01..FR-15 và NFR-01..NFR-11. Ví dụ FR-01 xem menu, FR-05 đặt đơn, FR-07 thanh toán idempotent, FR-10 state machine, FR-12 điểm thưởng, FR-13 PWA; NFR-01 p95 < 500 ms, NFR-03 bảo mật xác thực, NFR-04 toàn vẹn giao dịch, NFR-07 tính sẵn sàng, NFR-08 khả năng triển khai.", 1),
("MoSCoW là gì? Em xếp yêu cầu ra sao?", "Must / Should / Could / Won't (this time). Must: luồng menu → giỏ → đăng nhập → đặt đơn → thanh toán → xác nhận, state machine, NFR bảo mật và triển khai. Should: mã giảm giá, hủy đơn, điểm thưởng. Could: PWA. Won't (bản 2.0): giao diện nhân viên, thông báo đơn READY.", 1),
("Tiêu chí chấp nhận tốt phải như thế nào?", "Kiểm chứng được bằng đúng/sai, có điều kiện và kết quả cụ thể, viết được thành test. Ví dụ tốt: 'POST /payments thiếu Idempotency-Key trả 400'. Ví dụ kém: 'thanh toán phải an toàn'. Có thể viết dạng Given/When/Then.", 2),
("User story có cấu trúc thế nào? Cho ví dụ của đồ án.", "'Là <vai trò>, tôi muốn <mục tiêu> để <lợi ích>.' Ví dụ US-07: 'Là khách hàng, tôi muốn bấm thanh toán nhiều lần hoặc mất mạng mà không bị trừ tiền hai lần.' Tiêu chí: cùng Idempotency-Key chỉ tạo 1 đơn/1 giao dịch. A1 có US-01..US-09; A2 bổ sung US-10..US-14.", 1),
("Tiêu chí INVEST của user story?", "Independent (độc lập), Negotiable (thương lượng được), Valuable (có giá trị), Estimable (ước lượng được), Small (đủ nhỏ để làm trong một Sprint), Testable (kiểm thử được).", 2),
("Use-case trọng tâm em chọn là gì và vì sao?", "UC-05 Đặt và thanh toán đơn hàng, vì tạo ra doanh thu và chứa các rủi ro lớn nhất: trừ tiền hai lần, bán vượt kho, thanh toán lỗi.", 1),
("Đặc tả UC-05 gồm những mục nào?", "Mã/tên, actor chính (Khách hàng) và phụ (Cổng thanh toán), trigger (bấm Thanh toán ở /cart), yêu cầu liên quan, include/extend, tiền điều kiện (giỏ ≥ 1 món), hậu điều kiện thành công và thất bại, luồng chính 10 bước, luồng thay thế A1..A5, luồng ngoại lệ E1..E8, quy tắc đặc biệt, bảng tiêu chí → test.", 1),
("Luồng thay thế khác luồng ngoại lệ thế nào? Kể các luồng của UC-05.", "Thay thế (A): vẫn đạt mục tiêu theo đường khác. Ngoại lệ (E): không đạt, hệ thống xử lý lỗi có kiểm soát. A1 chưa đăng nhập; A2 nhập mã hợp lệ; A3 giá server khác giỏ; A4 gửi lặp cùng key; A5 thanh toán lại đơn PAYMENT_FAILED. E1 dữ liệu sai 400; E2 mã giảm giá sai; E3 hết hàng 409; E4 token hết hạn 401; E5 cổng từ chối 402; E6 đơn không thanh toán được 409; E7 key dùng cho đơn khác 409; E8 mất kết nối.", 2),
("Hậu điều kiện thành công của UC-05?", "Đúng 1 đơn PAID với giá server tính; đúng 1 payment SUCCESS gắn Idempotency-Key; tồn kho giảm đúng số ly; khách được cộng ⌊tổng/10.000⌋ điểm và có 1 LoyaltyTransaction EARN; giỏ được xóa; khách thấy trang /orders/:id.", 2),
("Quy tắc nghiệp vụ BR-01..BR-05 là gì?", "BR-01 đơn giá = giá gốc size M + chênh lệch size + tổng topping khác nhau. BR-02 giảm = ⌊tạm tính × % / 100⌋, không vượt trần. BR-03 điểm = ⌊tổng / 10.000⌋, cộng một lần khi PAID, thu hồi khi hủy. BR-04 giữ kho khi tạo đơn, trả kho khi hủy. BR-05 chỉ đơn PENDING/PAYMENT_FAILED được thanh toán.", 2),
("Làm sao chứng minh tiêu chí chấp nhận đã được dùng để viết test?", "Mỗi dòng SRS có cột Test với mã cụ thể (ví dụ FR-07 → INT-T08, T09, T10, T16, T17), và ma trận truy vết nối yêu cầu → use-case → sơ đồ → code → test. Tên test trong code bắt đầu bằng đúng mã đó.", 3),
])

ch("Sơ đồ Use Case", "Use case tổng quát A1 (13 use case) và A2 (UC-01..UC-12), use case UC-05.", ["a1/usecase.png", "a2/usecase-overview.png"], [
("Sơ đồ use case dùng để làm gì?", "Mô tả hệ thống từ góc nhìn bên ngoài: AI (actor) dùng hệ thống để LÀM GÌ (use case). Không mô tả cách làm bên trong hay thứ tự thời gian.", 1),
("Các thành phần của sơ đồ use case?", "Actor (người que hoặc «actor»), use case (hình elip, tên động từ + danh từ), system boundary (hình chữ nhật), association (đường nối actor – use case), include, extend, generalization.", 1),
("Include và extend khác nhau thế nào? Mũi tên chỉ hướng nào?", "Include: hành vi BẮT BUỘC, use case gốc luôn gọi use case được include; mũi tên đứt từ gốc tới use case được include. Extend: hành vi TÙY CHỌN, chỉ xảy ra khi có điều kiện; mũi tên đứt từ use case mở rộng về use case gốc.", 1),
("Actor của BrewLite là ai?", "Khách hàng (A2 tách Khách chưa đăng nhập và Khách hàng CUSTOMER, có generalization), Nhân viên quầy (STAFF), Cổng thanh toán (actor hệ thống, mô phỏng).", 1),
("Cổng thanh toán có phải actor không? Vì sao?", "Có. Actor là bất kỳ thực thể BÊN NGOÀI ranh giới hệ thống tương tác với hệ thống, có thể là người hoặc hệ thống khác. Cổng thanh toán là hệ thống ngoài nên vẽ là actor «system».", 2),
("Trong sơ đồ của em, quan hệ nào là include, quan hệ nào là extend?", "A1: UC5 Đặt đơn include UC4 Đăng nhập; UC6 Thanh toán include UC5; UC2 extend UC1; UC10 Áp mã extend UC5; UC11 Tích điểm extend UC6 (khi PAID); UC12 Thử lại thanh toán extend UC6 (khi PAYMENT_FAILED). A2: UC-05 include UC-04; UC-06 Áp mã extend UC-05; UC-07 Thử lại extend UC-05; UC-02 extend UC-01.", 2),
("A1 có bao nhiêu use case? A2 có bao nhiêu?", "A1: 13 use case (UC1..UC13). A2 (SRS 2.0): 12 use case UC-01..UC-12, thêm UC-10 Xem điểm thưởng và UC-12 Cài ứng dụng PWA.", 1),
("Generalization giữa Khách và Khách hàng nghĩa là gì?", "Khách hàng (đã đăng nhập) kế thừa mọi use case của Khách (xem menu, chi tiết, giỏ, đăng nhập) và có thêm use case riêng (đặt đơn, xem lịch sử, hủy đơn, xem điểm).", 2),
("Lỗi thường gặp khi vẽ use case?", "Đặt tên use case là danh từ hoặc tên màn hình; vẽ use case quá nhỏ như 'bấm nút'; dùng use case để vẽ thứ tự bước (đó là việc của activity); nhầm hướng mũi tên include/extend; nối actor với nhau; để actor bên trong ranh giới hệ thống.", 2),
])

ch("Sơ đồ dòng dữ liệu (DFD)", "DFD mức 0 và mức 1 của A1.", ["a1/dfd0.png", "a1/dfd1.png"], [
("DFD mô tả gì? Khác use case và activity thế nào?", "DFD mô tả DỮ LIỆU đi từ đâu, qua xử lý nào, được lưu ở đâu. Use case mô tả ai làm gì; activity mô tả thứ tự bước và điều kiện. DFD không có thứ tự thời gian hay rẽ nhánh.", 1),
("4 ký hiệu của DFD?", "Tác nhân ngoài (hình chữ nhật), tiến trình (hình tròn/chữ nhật bo góc, có số và động từ), kho dữ liệu (hai đường song song hoặc hộp hở, D1, D2...), luồng dữ liệu (mũi tên có nhãn là danh từ).", 1),
("DFD mức 0 (sơ đồ ngữ cảnh) của em có gì?", "Một tiến trình duy nhất '0 Hệ thống BrewLite' và 3 tác nhân ngoài: Khách hàng, Nhân viên, Cổng thanh toán, với các luồng vào/ra như yêu cầu đặt đơn, xác nhận, yêu cầu charge, kết quả thanh toán.", 1),
("DFD mức 1 có những tiến trình và kho nào?", "6 tiến trình: 1.0 Xác thực, 2.0 Tra cứu menu, 3.0 Tạo đơn, 4.0 Thanh toán (idempotent), 5.0 Quản lý trạng thái đơn, 6.0 Truy vấn lịch sử. 5 kho: D1 users, D2 products, D3 orders + order_items, D4 payments, D5 coupons.", 1),
("Các luật bắt buộc khi vẽ DFD?", "Luồng dữ liệu phải đi qua tiến trình: không nối trực tiếp tác nhân – tác nhân, tác nhân – kho, kho – kho. Mỗi tiến trình có ít nhất một luồng vào và một luồng ra (tránh hố đen, phép màu). Kho phải có luồng vào và ra. Cân bằng: luồng vào/ra mức con khớp với tiến trình cha.", 2),
("Hố đen, phép màu, xám là gì?", "Hố đen: tiến trình chỉ có vào không có ra. Phép màu: chỉ có ra không có vào. Hố xám (grey hole): đầu vào không đủ để tạo ra đầu ra.", 2),
("Cân bằng DFD là gì?", "Khi phân rã tiến trình cha thành mức con, tất cả luồng vào/ra của cha phải xuất hiện ở mức con (cùng tác nhân, cùng dữ liệu). Ví dụ luồng 'yêu cầu đặt đơn' từ Khách hàng ở mức 0 phải có ở mức 1 (vào tiến trình 3.0).", 2),
("Ở A2 bảng coupons đã đổi thành promotions. DFD có cần sửa không?", "Có, kho D5 nên đổi tên thành promotions và thêm kho loyalty_transactions (D6) nối với tiến trình 4.0 (cộng điểm) và 5.0 (thu hồi khi hủy). Đây là ví dụ cho việc sơ đồ phải được cập nhật qua pull request khi mô hình dữ liệu đổi.", 3),
])

ch("Sơ đồ hoạt động (Activity)", "Activity A1 (2 sơ đồ) và Activity-01 A2 có swimlane.", ["a1/activity-a.png", "a2/activity-checkout.png"], [
("Activity diagram dùng để làm gì?", "Mô tả luồng công việc từng bước của một quy trình, có rẽ nhánh, hợp nhánh, song song và trách nhiệm từng bên (swimlane).", 1),
("Các ký hiệu của activity diagram?", "Nút bắt đầu (chấm đen), hành động (hình chữ nhật bo góc), decision và merge (hình thoi), fork/join (thanh đen), nút kết thúc hoạt động (chấm đen trong vòng tròn), flow final (vòng tròn có dấu X), swimlane (làn), guard [điều kiện] trên nhánh.", 1),
("Decision khác fork thế nào?", "Decision chọn MỘT nhánh theo điều kiện (if/else). Fork chạy NHIỀU nhánh song song, join chờ tất cả xong mới đi tiếp.", 1),
("Activity-01 của A2 có những swimlane nào và đủ 3 trường hợp đề yêu cầu chưa?", "3 làn: Khách hàng, Next.js UI, NestJS API. Có đủ: hết hàng (ở bước chọn món: vô hiệu nút; ở bước giữ kho: 409 OUT_OF_STOCK), chưa đăng nhập (chuyển /login?next=/checkout), thanh toán thất bại (PAYMENT_FAILED, chọn thử lại hoặc hủy). Thêm lỗi tải menu và dữ liệu sai 400.", 2),
("Kể luồng hoạt động end-to-end theo Activity-01.", "Mở app → UI gọi GET /products (lỗi thì Thử lại) → khách chọn món, size, topping (hết hàng thì không thêm được) → thêm giỏ, lặp lại nếu chọn thêm → bấm Thanh toán → chưa đăng nhập thì đăng nhập/đăng ký → chọn phương thức, nhập mã → POST /orders → API validate (sai 400) → BEGIN, tính giá, giữ kho (thiếu 409) → lưu PENDING → POST /payments → khóa đơn, gọi cổng → từ chối: PAYMENT_FAILED (thử lại hoặc hủy) / chấp nhận: PAID, cộng điểm → xóa giỏ, /orders/:id → theo dõi PREPARING → READY → nhận tại quầy.", 2),
("Guard condition là gì? Yêu cầu gì với các nhánh?", "Điều kiện trong ngoặc vuông trên nhánh ra của decision, ví dụ [đủ tồn kho]. Các guard phải loại trừ nhau và bao phủ mọi trường hợp (không có trường hợp không nhánh nào đúng).", 2),
("Khi nào dùng swimlane?", "Khi quy trình có nhiều actor hoặc thành phần chịu trách nhiệm khác nhau, để thấy rõ bước nào do ai làm (khách, frontend, backend).", 1),
])

ch("Sơ đồ tuần tự (Sequence)", "5 sequence A1 (auth, tạo đơn, thanh toán, hủy, race) và Sequence-01 A2.", ["a1/seq-pay.png", "a2/sequence-checkout.png"], [
("Sequence diagram mô tả gì?", "Các đối tượng trao đổi thông điệp theo thứ tự thời gian (từ trên xuống) trong MỘT kịch bản cụ thể.", 1),
("Các thành phần của sequence diagram?", "Lifeline (đường đứt dọc dưới participant/actor), thanh kích hoạt, thông điệp đồng bộ (mũi tên liền đầu đặc), thông điệp trả về (mũi tên đứt), self-message, fragment alt/opt/loop/par, note, autonumber.", 1),
("alt, opt, loop khác nhau thế nào?", "alt: chọn một trong nhiều nhánh (if/else). opt: một nhánh có thể xảy ra hoặc không (if không else). loop: lặp lại. par: chạy song song.", 1),
("5 lifeline bắt buộc trong Sequence-01 A2?", "Customer → Next.js UI → NestJS API → Database → Payment Service.", 1),
("Sequence-01 thể hiện kiểm tra JWT và validate ở đâu?", "Ngay khi API nhận POST /orders: JwtAuthGuard kiểm tra chữ ký và hạn token (alt 401), ValidationPipe whitelist kiểm tra size S/M/L, qty 1–20, giỏ không rỗng (alt 400). Tương tự ở POST /payments.", 2),
("Transaction tạo đơn được vẽ thế nào?", "BEGIN → SELECT products → tính đơn giá, giảm giá → loop mỗi sản phẩm (theo id tăng dần, thử lại ≤ 8): UPDATE products SET stock = stock − qty, version = version + 1 WHERE id = ? AND version = ? AND stock >= qty → alt không đủ: ROLLBACK, 409; đủ: INSERT orders + order_items, COMMIT, 201.", 2),
("Idempotency thể hiện ở đâu trong sequence?", "Trước khi xử lý, API tìm payment theo Idempotency-Key. Đã có thì trả kết quả cũ (200/402 + header Idempotent-Replayed: true) và KHÔNG gọi Payment Service. Key mới thì BEGIN, SELECT ... FOR UPDATE khóa dòng đơn, kiểm tra lại key rồi mới gọi cổng.", 2),
("Sequence thanh toán: thành công và thất bại khác nhau thế nào?", "Thành công: UPDATE orders → PAID, INSERT loyalty_transactions EARN + tăng điểm, INSERT payments SUCCESS, COMMIT, 201. Thất bại: UPDATE orders → PAYMENT_FAILED, INSERT payments FAILED (kèm lý do), COMMIT, 402, không cộng điểm.", 2),
("Sequence race (A1) minh họa điều gì?", "Hai khách cùng mua sản phẩm cuối cùng. Cả hai đọc stock = 1, version = n. Người A cập nhật thành công (version → n+1). Người B UPDATE với version = n không khớp nên 0 dòng bị ảnh hưởng → đọc lại thấy stock = 0 → 409 OUT_OF_STOCK. Không ai làm kho âm.", 2),
("Sequence hủy đơn (A1) có gì?", "Khách POST /orders/:id/cancel → OrdersService kiểm tra quyền, assertTransition(status, CANCELLED) (self-message) → UPDATE ... WHERE status = <hiện tại> → hoàn kho (release) → nếu đã PAID thì thu hồi điểm → trả 201. Nhân viên PATCH /orders/:id/status chuyển PREPARING → READY → COMPLETED.", 2),
("Vì sao khóa dòng đơn khi thanh toán mà không dùng optimistic lock?", "Thanh toán chỉ trên MỘT đơn, ít tranh chấp nhưng cần tuần tự tuyệt đối và có gọi cổng ngoài. Khóa bi quan (FOR UPDATE) bắt các request song song cùng đơn phải chờ, tránh gọi cổng hai lần. Tồn kho thì nhiều đơn tranh chấp, mỗi lần cập nhật rất ngắn, nên dùng optimistic lock để có thông lượng tốt.", 3),
])

ch("Sơ đồ lớp (Class)", "Class domain + class service A1, Class-01 A2 có Promotion và LoyaltyTransaction.", ["a2/class-domain.png", "a1/class-service.png"], [
("Class diagram mô tả gì?", "Cấu trúc tĩnh: các lớp, thuộc tính, phương thức và quan hệ giữa chúng.", 1),
("Một lớp gồm mấy ngăn? Các ký hiệu phạm vi?", "3 ngăn: tên lớp, thuộc tính, phương thức. + public, - private, # protected, ~ package.", 1),
("Các loại quan hệ trong class diagram?", "Association (đường liền), aggregation (thoi rỗng, phần sống độc lập), composition (thoi đặc, phần chết theo tổng thể), dependency (mũi tên đứt), generalization (mũi tên liền đầu tam giác rỗng – kế thừa), realization (mũi tên đứt đầu tam giác rỗng – cài đặt interface).", 1),
("Aggregation và composition khác nhau thế nào? Ví dụ trong đồ án.", "Composition: phần không tồn tại ngoài tổng thể, xóa tổng thể thì phần mất theo – Order *-- OrderItem. Aggregation: phần có thể tồn tại độc lập. OrderItem chỉ THAM CHIẾU Product (association có hướng), xóa đơn không xóa sản phẩm.", 2),
("7 lớp bắt buộc của Class-01 A2 và enum?", "User, Product, Order, OrderItem, Payment, Promotion, LoyaltyTransaction. Enum: OrderStatus (7), Role (CUSTOMER, STAFF), PaymentMethod (WALLET, CARD), PaymentStatus (SUCCESS, FAILED), LoyaltyType (EARN, REVOKE), Size (S, M, L).", 1),
("Đọc bội số các quan hệ chính.", "User 1 — 0..* Order; Order 1 *-- 1..* OrderItem; OrderItem 0..* → 1 Product; Order 1 — 0..* Payment; User 1 — 0..* Payment; Order 0..* → 0..1 Promotion; User 1 — 0..* LoyaltyTransaction; Order 1 — 0..2 LoyaltyTransaction.", 2),
("Vì sao Order — LoyaltyTransaction là 0..2?", "Ràng buộc UNIQUE(orderId, type): mỗi đơn có tối đa một dòng EARN (khi PAID) và một dòng REVOKE (khi hủy đơn đã PAID). Đơn chưa thanh toán có 0 dòng.", 3),
("Vì sao passwordHash là private (-)?", "Đây là dữ liệu nhạy cảm, không được lộ ra ngoài lớp/API. Thực tế API không bao giờ trả trường này.", 1),
("Vì sao OrderItem lưu productName và unitPrice thay vì chỉ productId?", "Để giữ giá và tên TẠI THỜI ĐIỂM ĐẶT. Nếu sau này đổi giá hoặc tên sản phẩm, đơn cũ vẫn đúng như lúc khách trả tiền (dữ liệu lịch sử).", 2),
("Class diagram service (A1) cho thấy gì?", "Kiến trúc controller → service: AuthController → AuthService, OrdersController → OrdersService, PaymentsController → PaymentsService; OrdersService dùng StockService (reserve/release) và PromotionsService (discountFor/awardPoints); PaymentsService dùng OrdersService và MockPaymentGateway; controller phụ thuộc JwtAuthGuard và RolesGuard.", 2),
("Class diagram khác ERD thế nào?", "Class mô tả đối tượng trong code: có phương thức, kế thừa, enum, quan hệ composition. ERD mô tả bảng trong CSDL: khóa chính, khóa ngoại, kiểu dữ liệu, bội số theo ký hiệu chân chim, bảng trung gian cho N-N.", 2),
])

ch("ERD và cơ sở dữ liệu", "ERD A1 và thay đổi ở A2 (promotions, loyalty_transactions, FK, CHECK, migration).", ["a1/erd.png"], [
("Các bảng trong CSDL BrewLite hiện tại?", "users, products, orders, order_items, payments, promotions (A1 là coupons), loyalty_transactions (mới ở A2), và bảng migrations do TypeORM quản lý.", 1),
("PK, FK, UNIQUE khác nhau thế nào?", "PK định danh duy nhất một dòng. FK trỏ tới PK của bảng khác để giữ toàn vẹn tham chiếu. UNIQUE bắt giá trị không trùng nhưng không phải khóa chính (ví dụ users.email, payments.idempotencyKey).", 1),
("Ký hiệu chân chim đọc thế nào?", "| là đúng một, o là không (tùy chọn), chân chim là nhiều. ||--o{ : một bắt buộc tới không hoặc nhiều. ||--|{ : một tới một hoặc nhiều.", 1),
("Quan hệ 1-N thì đặt FK ở đâu? N-N thì sao?", "1-N: FK ở bảng phía N (orders.userId). N-N: tạo bảng trung gian chứa hai FK (ví dụ nếu một sản phẩm nhiều danh mục và ngược lại thì cần product_categories).", 1),
("Các ràng buộc toàn vẹn quan trọng trong CSDL?", "UNIQUE(payments.idempotencyKey); UNIQUE(orders.userId, idempotencyKey); UNIQUE(loyalty_transactions.orderId, type); UNIQUE(users.email); CHECK(stock >= 0); CHECK(loyaltyPoints >= 0); khóa ngoại orders → users/promotions, order_items → orders/products, payments → orders/users, loyalty_transactions → users/orders.", 2),
("Vì sao vừa kiểm tra trong code vừa đặt ràng buộc ở CSDL?", "Phòng thủ nhiều lớp. Code có thể có lỗi hoặc có đường ghi dữ liệu khác (script, test); CSDL là lớp cuối cùng bảo đảm không bao giờ có tồn kho âm, payment trùng key hay tham chiếu tới dòng không tồn tại.", 2),
("Cột version trong products dùng để làm gì?", "Optimistic locking: mỗi lần trừ kho tăng version; UPDATE chỉ thành công khi version chưa bị ai đổi (WHERE version = ?). Nếu 0 dòng bị ảnh hưởng nghĩa là có người cập nhật trước → đọc lại và thử lại.", 2),
("Migration là gì? Vì sao bỏ synchronize?", "Migration là tệp mô tả từng bước thay đổi schema (up) và cách hoàn tác (down), có lịch sử trong bảng migrations. synchronize tự sửa bảng theo entity, có thể xóa cột/dữ liệu, không có lịch sử, không rollback được, không an toàn cho production.", 2),
("Đồ án có những migration nào?", "InitialSchema (tạo bảng) và AddRelationsAndChecks (khóa ngoại, CHECK stock >= 0, CHECK loyaltyPoints >= 0). Đã kiểm tra run, revert hai lần, run lại; migration:generate báo No changes nên entity khớp migration.", 2),
("Chuẩn hóa: bảng orders có vi phạm 3NF không khi lưu total?", "total là giá trị dẫn xuất (subtotal − discount). Lưu lại là PHI CHUẨN HÓA CÓ CHỦ Ý để giữ số tiền đã chốt lúc thanh toán và truy vấn nhanh; giá trị được tính một lần trong transaction nên không lệch.", 3),
])

ch("Máy trạng thái (State machine)", "State machine đơn hàng và state machine của một Idempotency-Key.", ["a1/state-order.png", "a1/state-payment.png"], [
("State machine diagram mô tả gì?", "Vòng đời của MỘT đối tượng: các trạng thái và sự kiện/điều kiện làm nó chuyển trạng thái. Nhãn chuyển: sự kiện [guard] / hành động.", 1),
("Đơn hàng có những trạng thái nào?", "7 trạng thái: PENDING, PAID, PREPARING, READY, COMPLETED, PAYMENT_FAILED, CANCELLED. COMPLETED và CANCELLED là trạng thái kết thúc.", 1),
("Các chuyển tiếp hợp lệ?", "PENDING → PAID, PAYMENT_FAILED, CANCELLED; PAYMENT_FAILED → PENDING, CANCELLED; PAID → PREPARING, CANCELLED; PREPARING → READY; READY → COMPLETED. Tổng 9 cặp hợp lệ trên 49 cặp (7×7); 40 cặp còn lại bị chặn.", 1),
("Chuyển trạng thái sai thì sao? Code nằm ở đâu?", "Hàm assertTransition trong apps/api/src/orders/order-status.ts ném 409 INVALID_TRANSITION. Unit test UT-01..04 kiểm tra đủ 49 cặp.", 1),
("Hai request đồng thời cùng chuyển một đơn thì sao?", "Câu UPDATE có điều kiện WHERE id = ? AND status = <trạng thái hiện tại>: chỉ request đầu tiên đổi được dòng, request sau thấy 0 dòng bị ảnh hưởng và bị từ chối.", 2),
("Khách hủy được đơn ở trạng thái nào? Hủy thì có gì xảy ra?", "PENDING, PAYMENT_FAILED, PAID (chưa pha chế). Hệ thống trả kho; nếu đã PAID thì thu hồi điểm (ghi LoyaltyTransaction REVOKE). PREPARING trở đi thì không hủy được (409).", 1),
("Vì sao PAYMENT_FAILED được quay lại PENDING?", "Để khách thử lại thanh toán trên CÙNG đơn (giữ nguyên giá và tồn kho đã giữ) thay vì tạo đơn mới làm giữ kho hai lần (lỗi D11 đã sửa).", 2),
("State machine của Idempotency-Key gồm gì?", "Key mới → Đang xử lý (trong transaction, khóa dòng đơn) → SUCCESS hoặc FAILED (theo cổng) → Đã lưu (INSERT payments, UNIQUE key). Nhánh Từ chối khi đơn không thanh toán được (409, không lưu). Gửi lại key ở trạng thái Đã lưu thì trả kết quả cũ.", 2),
("Ai được chuyển PREPARING, READY, COMPLETED?", "Chỉ nhân viên (role STAFF) qua PATCH /orders/:id/status, bảo vệ bằng RolesGuard; khách gọi nhận 403. Nhân viên không được đặt PAID bằng tay (400) vì PAID chỉ do thanh toán sinh ra.", 2),
])

ch("Kiến trúc hệ thống", "Component, package, deployment (A1), C4, phân lớp, ADR, deployment production (A2).", ["a1/component.png", "a2/c4-container.png", "a2/deployment-production.png"], [
("Kiến trúc tổng thể của BrewLite?", "Ba thành phần: Web app Next.js 14 (mobile-first, PWA) gọi REST API NestJS 10 qua HTTPS/JSON với Bearer JWT; API dùng TypeORM truy cập PostgreSQL 16. Payment adapter MockPaymentGateway chạy trong API. Đóng gói bằng Docker, chạy local bằng docker compose, production trên Render.", 1),
("Mô hình C4 gồm những mức nào? Đồ án vẽ mức nào?", "Context (hệ thống và người dùng, hệ thống ngoài), Container (ứng dụng, CSDL chạy riêng), Component (thành phần trong container), Code. Đồ án vẽ mức 1 và 2; mức 3 thể hiện bằng cấu trúc module NestJS.", 1),
("Backend chia lớp thế nào?", "Presentation: controller, DTO + class-validator, guard (không chứa nghiệp vụ). Application/Domain: service và hàm thuần (unitPrice, computeDiscount, assertTransition). Infrastructure: entity, migration, MockPaymentGateway, PostgreSQL.", 1),
("NestJS module gồm những gì? Đồ án có module nào?", "Module gom controller, provider (service) và import/export. Đồ án: auth, users, products, orders, payments, promotions, loyalty, seed, health. Module chỉ dùng nhau qua service được export.", 2),
("Component, package, deployment diagram khác nhau thế nào?", "Component: các thành phần phần mềm và giao diện giữa chúng (có gì). Package: cách nhóm mã nguồn và phụ thuộc giữa các gói (nhóm ra sao). Deployment: phần mềm chạy trên node nào, cổng, kết nối (chạy ở đâu).", 1),
("ADR là gì? Đồ án có những ADR nào?", "Architecture Decision Record: ghi một quyết định kiến trúc gồm bối cảnh, phương án, quyết định, hệ quả. 7 ADR: 001 monorepo; 002 modular monolith; 003 PostgreSQL + TypeORM + migration; 004 migration khi khởi động trong 1 transaction; 005 idempotency + khóa dòng + optimistic lock; 006 Render + GHCR + GitHub Actions; 007 JWT Bearer + bcrypt.", 1),
("Vì sao chọn modular monolith thay vì microservices?", "Đặt đơn, trừ kho, thanh toán và cộng điểm cần một transaction ACID chung. Microservices cần saga/outbox, nhiều container, chi phí vận hành cao, không hợp với nhóm một người và lưu lượng nhỏ. Ranh giới module vẫn cho phép tách sau này (ví dụ tách payment).", 2),
("Deployment diagram production có những gì?", "3 vùng: LOCAL (laptop, docker compose), CI (GitHub Actions runner, GitHub Secrets, GHCR), PRODUCTION (Render Singapore: Render Edge HTTPS, brewlite-web cổng 3000, brewlite-api cổng 3001, brewlite-db PostgreSQL 16 có persistent disk, không public). Người dùng → HTTPS 443 → Edge → web/api; api → db qua Internal URL 5432.", 1),
("Làm sao chứng minh deployment diagram truy vết được tới mã nguồn?", "Bảng cuối architecture.md: brewlite-web ↔ apps/web + Dockerfile + render.yaml; brewlite-api ↔ apps/api; brewlite-db ↔ apps/api/src/database + render.yaml databases; GHCR ↔ job image trong cd.yml; secret ↔ .env.example, render.yaml envVars, GitHub Secrets; health ↔ health.controller.ts.", 2),
("Docker Compose local gồm những gì?", "3 dịch vụ: db (postgres:16-alpine, cổng 5432, healthcheck pg_isready, volume brewlite-db), api (NestJS 3001, chờ db khỏe, chạy migration + seed), web (Next.js 3000, chờ api khỏe; NEXT_PUBLIC_API_URL nhúng lúc build).", 1),
("Vì sao NEXT_PUBLIC_API_URL đổi thì phải build lại web?", "Next.js thay biến NEXT_PUBLIC_* vào mã JavaScript lúc build để trình duyệt dùng được. Đổi giá trị lúc chạy không có tác dụng, phải build lại image.", 2),
("Sitemap (A1) có những trang nào?", "/ Menu, /products/:id, /cart, /login, /register, /checkout, /orders, /orders/:id. Chưa đăng nhập bấm Thanh toán → /login?next=/checkout; thanh toán thành công → /orders/:id; thất bại → ở lại /checkout.", 1),
])

ch("Luồng nghiệp vụ và Task 10", "Giá, khuyến mãi, điểm, idempotency, tồn kho đồng thời, mã lỗi HTTP.", [], [
("Giá một ly tính thế nào? Ví dụ.", "Giá gốc (size M) + chênh lệch size (S −5.000, M 0, L +7.000) + tổng topping (Trân châu 5.000, Kem 7.000, Thạch dừa 5.000, Espresso shot 10.000; mỗi loại tính một lần). Cappuccino 45.000 size L + Trân châu = 45.000 + 7.000 + 5.000 = 57.000đ.", 1),
("Vì sao giá phải tính ở server?", "Client có thể bị sửa (DevTools, gọi API trực tiếp). Server tính lại từ bảng giá gốc + size + topping nên không ai gửi giá thấp để gian lận. Frontend chỉ hiển thị để tiện.", 1),
("Hai mã giảm giá hoạt động thế nào?", "BREW10: giảm 10%, tối đa 20.000đ, không yêu cầu đơn tối thiểu. WELCOME20: giảm 20% cho đơn từ 100.000đ, tối đa 50.000đ. Giảm làm tròn xuống. Mã không phân biệt hoa thường; sai, hết hạn hoặc chưa đủ tối thiểu trả 400.", 1),
("Điểm thưởng tính và lưu thế nào?", "⌊tổng thanh toán / 10.000⌋, cộng đúng một lần khi đơn chuyển PAID (cờ pointsAwarded + UNIQUE(orderId, type)). Hủy đơn đã PAID thì thu hồi đúng số điểm. Mỗi lần ghi một dòng loyalty_transactions (EARN/REVOKE); users.loyaltyPoints là số dư; GET /loyalty/me trả số dư và lịch sử.", 1),
("Idempotent là gì? Vì sao thanh toán cần idempotent?", "Gửi một yêu cầu nhiều lần cho kết quả như gửi một lần. Khách có thể bấm nhiều lần hoặc mạng rớt rồi trình duyệt gửi lại; nếu không idempotent sẽ trừ tiền hai lần.", 1),
("Idempotency được hiện thực bằng những cơ chế nào?", "Header Idempotency-Key bắt buộc ở POST /payments (thiếu 400); cột idempotencyKey UNIQUE; tìm key trước khi xử lý (có thì trả kết quả cũ, 200 + Idempotent-Replayed: true); khóa dòng đơn SELECT ... FOR UPDATE rồi kiểm tra lại key; key dùng cho đơn khác trả 409. POST /orders cũng hỗ trợ key (UNIQUE userId + key), 5 request đồng thời chỉ tạo 1 đơn.", 2),
("Chống bán vượt tồn kho thế nào?", "Optimistic locking: UPDATE products SET stock = stock − qty, version = version + 1 WHERE id = ? AND version = ? AND stock >= qty. 0 dòng → đọc lại, thử lại tối đa 8 lần; sắp xếp id để thứ tự khóa nhất quán; thiếu hàng → 409 OUT_OF_STOCK và rollback cả đơn. CHECK stock >= 0 là lớp bảo vệ cuối. Test: 12 khách tranh 5 ly ra đúng 5 đơn.", 2),
("Optimistic và pessimistic locking khác nhau ra sao?", "Pessimistic khóa dữ liệu trước khi sửa, người khác phải chờ (SELECT ... FOR UPDATE). Optimistic không khóa, kiểm tra xung đột lúc ghi bằng version, xung đột thì thử lại. Pessimistic hợp tranh chấp cao hoặc thao tác dài; optimistic hợp xung đột thấp, thao tác ngắn, cần thông lượng.", 2),
("Vì sao sắp xếp id sản phẩm trước khi trừ kho?", "Để mọi giao dịch truy cập dòng theo cùng một thứ tự, tránh hai giao dịch giữ dòng theo thứ tự ngược nhau gây xung đột/deadlock.", 3),
("Mã HTTP trong đồ án?", "201 tạo thành công; 200 phát lại idempotent; 400 dữ liệu sai/thiếu key/mã giảm giá sai; 401 chưa đăng nhập/token sai; 402 thanh toán thất bại; 403 không đủ quyền; 404 không tìm thấy; 409 xung đột (INVALID_TRANSITION, OUT_OF_STOCK, ORDER_NOT_PAYABLE, key dùng cho đơn khác, email trùng).", 1),
("3 tiêu chí chấm của Task 10 (A1) và cách chứng minh?", "(a) Chặn chuyển trạng thái sai → UT-01..04 (49 cặp) và INT-T11. (b) Gửi hai lần cùng Idempotency-Key chỉ tạo một đơn → INT-T14, T15 (5 request đồng thời). (c) Đặt đồng thời không vượt tồn kho → INT-T18..T20 (12 khách/5 ly, 30 khách/10 ly).", 1),
("Thanh toán thất bại thì dữ liệu ra sao?", "Đơn chuyển PAYMENT_FAILED, lưu payment FAILED cùng key và lý do, COMMIT, trả 402. Kho vẫn giữ cho đơn, giỏ hàng còn nguyên, không cộng điểm. Khách thử lại bằng key mới: đơn về PENDING rồi thanh toán.", 1),
("Nếu cổng thanh toán trừ tiền thành công nhưng server sập trước COMMIT thì sao?", "Đây là giới hạn của bản mô phỏng: transaction rollback nên đơn vẫn PENDING dù tiền đã trừ. Với cổng thật cần gửi Idempotency-Key sang cổng, dùng webhook từ cổng và job đối soát để cập nhật đơn theo kết quả thực tế (outbox/reconciliation). Đã ghi trong hướng phát triển.", 3),
])

ch("Bảo mật và xác thực", "JWT, bcrypt, phân quyền, validate, CORS, secret.", [], [
("JWT là gì? Cấu trúc thế nào?", "JSON Web Token gồm 3 phần header.payload.signature mã hóa base64url. Server ký bằng JWT_SECRET (HS256); client gửi trong header Authorization: Bearer <token>; server kiểm tra chữ ký và hạn (1 ngày) mà không cần lưu phiên.", 1),
("Payload JWT có bị mã hóa không? Có nên để mật khẩu trong đó?", "Không, chỉ mã hóa base64, ai cũng đọc được; chữ ký chỉ chống sửa. Không đặt dữ liệu nhạy cảm, chỉ id, email, role.", 2),
("Vì sao băm mật khẩu bằng bcrypt mà không dùng MD5/SHA?", "bcrypt có salt riêng mỗi mật khẩu và cố ý chậm (cost 10, khoảng 68 ms) để chống dò mật khẩu hàng loạt và rainbow table. MD5/SHA quá nhanh nên dễ bị brute-force.", 1),
("Phân quyền được thực hiện thế nào?", "JwtAuthGuard bảo vệ route cần đăng nhập; RolesGuard + @Roles('STAFF') cho API nhân viên; service kiểm tra khách chỉ xem/hủy đơn của chính mình (403).", 1),
("Validate đầu vào ở backend thế nào?", "ValidationPipe toàn cục với whitelist (bỏ trường lạ) và forbidNonWhitelisted (gửi trường lạ thì 400), DTO dùng class-validator: email hợp lệ, mật khẩu ≥ 6 ký tự, size thuộc S/M/L, qty 1–20, method thuộc WALLET/CARD.", 1),
("CORS là gì? Lỗi G07 là gì?", "CORS là cơ chế trình duyệt chỉ cho trang ở origin khác gọi API khi server cho phép. Lỗi G07: không đặt CORS_ORIGIN thì API nhận mọi nguồn; đã sửa để mặc định chỉ http://localhost:3000 và production đặt đúng URL web.", 2),
("Secret được quản lý thế nào ở production?", ".env không commit; .env.example chỉ có giá trị giả; JWT_SECRET do Render sinh; deploy hook trong GitHub Secrets (environment production), GitHub che trong log; CSDL không public; gitleaks quét lịch sử git mỗi PR; production thiếu biến hoặc JWT_SECRET < 32 ký tự thì app không khởi động.", 2),
("Lưu JWT trong localStorage có rủi ro gì? Cải tiến thế nào?", "Nếu trang bị XSS, script độc đọc được token. Giảm thiểu: React tự escape, không dùng dangerouslySetInnerHTML, token hết hạn 1 ngày. Cải tiến: cookie HttpOnly + SameSite và refresh token xoay vòng.", 3),
("Lỗi C07 là gì?", "Token hết hạn khiến giao diện kẹt (gọi API liên tục lỗi). Sửa: nhận 401 thì tự đăng xuất và chuyển về /login, giỏ hàng giữ nguyên.", 1),
])

ch("Kiểm thử", "Unit, integration, component, E2E, bộ 55 kịch bản giao diện, 6 lỗi đã sửa.", [], [
("Các mức kiểm thử trong đồ án?", "Unit test (hàm thuần: state machine, giá, khuyến mãi, cấu hình) – 15; integration test API với PostgreSQL thật – 27; test component web Vitest – 7; E2E Playwright luồng menu → xác nhận – 1; kiểm thử giao diện thủ công/tự động 55 kịch bản, 224 điểm kiểm tra (A1). Tổng test tự động A2: 50.", 1),
("Unit test khác integration test và E2E thế nào?", "Unit: kiểm tra một đơn vị nhỏ độc lập, nhanh, không cần CSDL. Integration: kiểm tra nhiều thành phần chạy cùng nhau (HTTP + service + PostgreSQL thật). E2E: kiểm tra như người dùng thật trên trình duyệt, đi qua toàn bộ hệ thống.", 1),
("Kim tự tháp kiểm thử là gì?", "Nhiều unit test ở đáy (rẻ, nhanh), ít integration hơn ở giữa, rất ít E2E ở đỉnh (chậm, dễ vỡ). Đồ án theo đúng tỉ lệ đó: 15 unit + 27 integration + 7 component, 1 E2E.", 2),
("Integration test dùng CSDL nào? Có ảnh hưởng dữ liệu thật không?", "CSDL riêng brewlite_test (TEST_DATABASE_URL). Mỗi lần chạy xóa schema (dropSchema) rồi chạy lại toàn bộ migration, nên không ảnh hưởng dữ liệu thật và đồng thời chứng minh migration tái tạo được CSDL.", 2),
("Test đồng thời tồn kho viết thế nào?", "Tạo sản phẩm còn 5 ly, bắn 12 request POST /orders song song bằng Promise.all, khẳng định đúng 5 request 201, 7 request 409 và stock cuối = 0, không âm.", 2),
("E2E-T01 đi qua những bước nào?", "Mở / trên khung Pixel 7 → bấm Cappuccino → chọn size L → Thêm vào giỏ → /cart có 1 dòng → Thanh toán → bị chuyển /login → Đăng ký tài khoản mới → về /checkout → chọn Ví điện tử → Xác nhận thanh toán → /orders/:id thấy 'Đã thanh toán' → /orders thấy đơn.", 1),
("Test component Menu kiểm tra gì?", "FE-T01: trạng thái loading (role status), danh sách có giá VND và nhãn Hết hàng, link tới /products/:id, trạng thái 'Menu đang trống', lỗi kết nối có nút Thử lại và gọi lại API. Dùng vi.mock để giả lập api.", 2),
("6 lỗi nghiệp vụ tìm được là gì?", "F04 (cao) giá đổi khi khách đang xem giỏ mà vẫn thanh toán → so tổng, hỏi lại. D11 thanh toán lỗi rồi tải lại tạo đơn thứ hai → dùng lại đơn cũ. D12 thanh toán lại từ chi tiết đơn nhưng giỏ không xóa → xóa đúng món. E06 hủy đơn PAID không thu hồi điểm → revokePoints. C07 token hết hạn kẹt giao diện → tự đăng xuất. G07 CORS nhận mọi nguồn → mặc định localhost:3000.", 2),
("Hộp đen và hộp trắng khác nhau thế nào? Đồ án dùng loại nào?", "Hộp đen: thiết kế test từ đặc tả, không nhìn code (E2E, kịch bản giao diện, phần lớn integration theo API). Hộp trắng: dựa trên cấu trúc code, nhánh, đường đi (unit test state machine phủ đủ 49 cặp). Đồ án dùng cả hai.", 2),
("Phân vùng tương đương và giá trị biên áp dụng thế nào?", "Ví dụ qty hợp lệ 1–20: phân vùng < 1, 1–20, > 20; giá trị biên 0, 1, 20, 21. WELCOME20: đơn 99.999 (không áp), 100.000 (áp). Mật khẩu 5 và 6 ký tự.", 2),
])

ch("DevOps: Docker, migration, CI/CD, triển khai", "Task 4.4, 5.2, 5.3, 5.4 của A2.", ["a2/deployment-production.png"], [
("CI và CD khác nhau thế nào?", "CI (Continuous Integration): mỗi thay đổi được tích hợp và kiểm tra tự động (lint, test, build) để phát hiện lỗi sớm. CD: Continuous Delivery tự động đóng gói và luôn sẵn sàng triển khai; Continuous Deployment tự động triển khai lên production khi qua kiểm tra.", 1),
("Pipeline CI của em gồm những bước nào? Chạy khi nào?", "Chạy khi mở/cập nhật PR vào main. Job quality (matrix api, web): Install → Lint → Unit Test → Build. Sau đó integration test với PostgreSQL service, E2E Playwright, gitleaks quét secret.", 1),
("Làm sao PR không merge được khi CI lỗi?", "Bật branch protection cho main: Require a pull request before merging + Require status checks to pass (chọn các job CI). Check đỏ thì nút Merge bị khóa.", 1),
("Pipeline CD có những bước nào?", "Push/tag → quality gate (gọi lại ci.yml) → build Docker image → tag commit SHA (và semver khi có tag) → push GHCR → gọi deploy hook Render cho API (migration chạy khi container khởi động) → chờ /health báo đúng SHA → deploy web → smoke test → lỗi thì rollback về SHA trước và dừng pipeline với lỗi → tag thì tạo GitHub Release.", 1),
("Vì sao tag image bằng commit SHA?", "SHA là duy nhất và bất biến, biết chính xác code nào đang chạy, rollback chỉ là deploy lại một image cũ. latest thì thay đổi theo thời gian nên không truy vết được.", 2),
("Migration chạy ở đâu và an toàn thế nào?", "Khi container API mới khởi động, mọi migration chưa chạy nằm trong một transaction. Lỗi thì rollback, app dừng, health check không đạt, Render không chuyển traffic, bản cũ vẫn chạy và pipeline rollback. Migration viết tương thích ngược (expand/contract) để rollback image vẫn chạy.", 2),
("Smoke test kiểm tra gì?", "API /health trả status ok, db up và version đúng SHA vừa deploy; GET /products có dữ liệu; web /health đúng SHA; trang Menu trả 200 có chữ BrewLite; manifest PWA đúng. Có thử lại vì dịch vụ cần thời gian kéo image và khởi động.", 1),
("Rollback có những cách nào?", "Tự động trong pipeline khi deploy/smoke test lỗi (deploy lại SHA đọc được từ /health trước khi deploy). Bằng tay: Actions → CD → Run workflow với rollback_to = <SHA>. Trên Render: Events → chọn bản trước → Rollback. Hoàn tác schema hiếm khi cần: migration:revert:prod.", 1),
("Health check endpoint trả gì?", "API GET /health: {status, db, migrations, version (commit SHA), uptime}; 200 khi CSDL trả lời SELECT 1, 503 khi CSDL lỗi. Web GET /health: {status, service, version}. Render dùng làm health check; pipeline dùng để xác nhận đúng phiên bản.", 1),
("Vì sao chọn Render và GHCR?", "Miễn phí, HTTPS tự động, chạy được Docker image, PostgreSQL có Internal URL, deploy hook nhận image theo SHA, hạ tầng khai báo bằng render.yaml. GHCR gắn liền GitHub, đăng nhập bằng GITHUB_TOKEN. Hạn chế: gói miễn phí ngủ sau 15 phút, Postgres miễn phí hết hạn 30 ngày.", 2),
("render.yaml dùng để làm gì?", "Blueprint – hạ tầng dưới dạng code: khai báo brewlite-db (Postgres 16, Singapore, ipAllowList rỗng), brewlite-api và brewlite-web (runtime image từ GHCR, healthCheckPath /health, autoDeploy false), biến môi trường (DATABASE_URL lấy từ DB, JWT_SECRET sinh tự động, CORS_ORIGIN nhập tay).", 2),
("Log được ghi thế nào?", "Middleware RequestLogger ghi một dòng mỗi request {method, path, status, ms}, JSON ở production, 5xx mức error, 4xx mức warn, bỏ qua /health 200, không ghi header, body, query. Xem trên Render Logs.", 1),
("PWA là gì? Đồ án làm những gì cho PWA?", "Progressive Web App: web cài được lên màn hình chính, chạy như app, có khả năng ngoại tuyến. Đồ án có app/manifest.ts (name, short_name, start_url, display standalone, icon 192/512/maskable), service worker public/sw.js (trang network-first, tài nguyên tĩnh cache-first, không cache API), trang offline.html, đăng ký service worker chỉ ở production.", 1),
("Vì sao service worker không cache API?", "Giá, tồn kho, trạng thái đơn phải luôn mới; cache API có thể khiến khách thấy giá cũ hoặc đơn sai trạng thái. Hơn nữa API ở origin khác nên service worker để mạng xử lý.", 2),
("Dockerfile multi-stage là gì? Có lợi gì?", "Stage build cài devDependencies và build; stage chạy chỉ copy dist/node_modules production. Image nhỏ hơn, ít bề mặt tấn công hơn. Container chạy bằng user node (không phải root) và có HEALTHCHECK.", 2),
("Nếu Render đang ngủ lúc thầy mở link thì sao?", "Gói miễn phí ngủ sau 15 phút không có request, lần đầu mất khoảng 1 phút để khởi động. Em mở web và /health trước giờ chấm khoảng 2 phút; nếu đang chờ thì giải thích đây là đặc điểm gói miễn phí đã ghi trong rủi ro R-04.", 3),
])

ch("Demo giao diện và chức năng", "Kịch bản demo và các yêu cầu thao tác thầy có thể đưa ra. Cột phải là kết quả em cần chỉ ra trên màn hình.", ["shots/menu.png"], [
("Thầy: 'Em demo luồng đặt hàng từ đầu đến cuối.'", "Mở web trên điện thoại hoặc DevTools khung mobile → Menu → chọn Cappuccino, size L, Trân châu (giá 57.000đ) → Thêm vào giỏ → Giỏ hàng → Thanh toán → đăng nhập → chọn Ví điện tử, nhập BREW10 → Xác nhận → màn hình 'Đã thanh toán' có mã đơn → Lịch sử đơn. Chỉ /health để thấy version và db up.", 1),
("Thầy: 'Chưa đăng nhập bấm thanh toán thì sao?'", "Đăng xuất, thêm món, bấm Thanh toán → bị chuyển /login?next=/checkout; đăng nhập xong quay lại /checkout, giỏ giữ nguyên.", 1),
("Thầy: 'Thanh toán thất bại thì sao?'", "Ở trang thanh toán bật ô 'Mô phỏng thanh toán lỗi' → Xác nhận → báo thất bại, đơn PAYMENT_FAILED, giỏ còn nguyên. Tắt ô, bấm thử lại → đơn PAID, vẫn là cùng mã đơn (không tạo đơn mới).", 1),
("Thầy: 'Bấm thanh toán nhiều lần có bị trừ tiền hai lần không?'", "Chạy integration test INT-T16 hoặc gọi API bằng scripts/demo-api.ps1/Postman: gửi hai lần POST /payments cùng Idempotency-Key → lần 1 trả 201, lần 2 trả 200 với header Idempotent-Replayed: true; trong bảng payments chỉ có 1 dòng.", 2),
("Thầy: 'Chứng minh không bán vượt tồn kho.'", "Chạy npm run test:integration và chỉ INT-T18 (12 khách tranh 5 ly → đúng 5 đơn, kho 0). Hoặc mở hai tab cùng mua món chỉ còn 1 ly: tab sau nhận 'không đủ hàng'.", 2),
("Thầy: 'Áp mã WELCOME20 cho đơn 90.000đ được không?'", "Không. Đơn tối thiểu 100.000đ nên báo lỗi 'Đơn tối thiểu ...'. Thêm món cho đủ 100.000đ thì áp được, giảm 20% tối đa 50.000đ.", 1),
("Thầy: 'Hủy đơn đã thanh toán thì điểm ra sao?'", "Vào chi tiết đơn PAID → Hủy đơn → trạng thái CANCELLED, kho được trả; gọi GET /loyalty/me thấy số dư giảm và có dòng REVOKE (INT-T26).", 2),
("Thầy: 'Nhân viên cập nhật trạng thái đơn thế nào?'", "Đăng nhập staff@brewlite.local, gọi PATCH /orders/:id/status với status PREPARING → READY → COMPLETED (Postman hoặc demo-api.ps1). Khách tải lại chi tiết đơn thấy trạng thái đổi. Thử nhảy cóc PENDING → COMPLETED nhận 409.", 2),
("Thầy: 'Tắt backend thì giao diện thế nào?'", "Dừng API → trang Menu hiện 'Không kết nối được máy chủ' và nút Thử lại; bật lại API, bấm Thử lại thì menu hiện ra.", 1),
("Thầy: 'Cài app lên điện thoại được không?'", "Mở URL production trên Chrome Android → menu ⋮ → Cài đặt ứng dụng / Thêm vào màn hình chính (Safari iOS: Chia sẻ → Thêm vào MH chính). Mở ra chạy toàn màn hình. Mất mạng khi mở trang mới thấy trang ngoại tuyến.", 1),
("Thầy: 'Cho xem pipeline CI/CD.'", "Mở GitHub → Actions: lần chạy CI trên PR (các job xanh), PR demo/ci-fail bị đỏ ở bước Lint và nút Merge bị khóa; lần chạy CD trên main với Summary 'Production đang chạy <SHA>'; lần rollback. Mở /health để đối chiếu SHA.", 1),
("Thầy: 'Sửa một dòng code rồi triển khai lại.'", "Tạo nhánh feat/..., sửa (ví dụ đổi chữ trên trang), commit theo Conventional Commits, mở PR → CI chạy → merge → CD build image SHA mới, deploy, smoke test → /health hiển thị SHA mới.", 3),
("Thầy: 'Chạy hệ thống trên máy em.'", "docker compose up --build → web localhost:3000, API localhost:3001/health. Tài khoản nhân viên staff@brewlite.local / staff123 (local).", 1),
("Thầy: 'Cho xem dữ liệu trong CSDL sau khi đặt đơn.'", "psql hoặc pgAdmin: SELECT status, total FROM orders ORDER BY id DESC LIMIT 1; SELECT * FROM payments WHERE \"orderId\" = ...; SELECT stock, version FROM products WHERE id = ...; SELECT * FROM loyalty_transactions.", 2),
])

ch("Câu hỏi mở rộng và câu hỏi khó", "Câu hỏi 'tại sao', 'nếu... thì sao' và hướng phát triển.", [], [
("Hạn chế lớn nhất của sản phẩm là gì?", "Cổng thanh toán mô phỏng, chưa hoàn tiền khi hủy đơn đã thanh toán; đơn PENDING chưa tự hết hạn nên có thể giữ kho mãi; chưa có giao diện nhân viên; JWT trong localStorage; gói miễn phí Render ngủ và Postgres hết hạn 30 ngày; E2E chỉ chạy Chromium, chưa kiểm thử tải.", 1),
("Nếu có thêm thời gian, em cải tiến gì trước?", "Đơn PENDING hết hạn sau 15 phút và nhả kho (cron/job); giao diện barista có hàng đợi và thông báo thời gian thực (WebSocket/Web Push) khi READY; cổng thật + webhook + hoàn tiền; cookie HttpOnly + refresh token; rate limit /auth.", 2),
("Nếu có 10.000 người dùng đồng thời thì sao?", "Scale ngang API (nhiều instance, stateless nhờ JWT), connection pool và chỉ mục CSDL, cache menu (CDN/Redis), chuyển migration sang job pre-deploy để tránh nhiều instance cùng chạy, tách hàng đợi cho thông báo; kiểm thử tải bằng k6 trước.", 3),
("Vì sao không dùng Redis để khóa tồn kho?", "PostgreSQL đã có transaction, khóa dòng và optimistic lock đủ cho quy mô này; thêm Redis là thêm một thành phần phải vận hành và một nguồn sự thật thứ hai dễ lệch dữ liệu.", 3),
("Đổi từ coupons sang promotions có làm hỏng dữ liệu cũ không?", "A2 dùng migration InitialSchema tạo bảng promotions từ đầu; CSDL tạo bởi A1 (synchronize) cần tạo lại một lần (docker compose down -v). Ở production thật sẽ viết migration đổi tên bảng (ALTER TABLE ... RENAME) để giữ dữ liệu.", 3),
("Monorepo có nhược điểm gì?", "CI chạy cả hai app mỗi PR; repo lớn dần; quyền truy cập không tách theo app. Khắc phục: lọc job theo đường dẫn thay đổi, cache npm.", 2),
("Nếu migration mới xóa một cột mà rollback image về bản cũ đang dùng cột đó?", "Bản cũ sẽ lỗi. Vì vậy quy tắc expand/contract: bản N thêm cột mới và ngừng dùng cột cũ; bản N+1 (sau khi chắc chắn không rollback) mới xóa cột cũ.", 3),
("Tại sao không dùng Vercel cho Next.js?", "Vercel tốt cho Next.js nhưng sẽ chia hệ thống ra hai nền tảng (web ở Vercel, API + DB ở nơi khác), thêm cấu hình và secret. Render chạy được cả ba thành phần bằng Docker image, cùng một cơ chế deploy hook và rollback.", 2),
("Làm sao biết code đang chạy trên production là phiên bản nào?", "Gọi /health của API và web, trường version là commit SHA; đối chiếu với lịch sử git và image trên GHCR.", 1),
("Đồ án có áp dụng nguyên lý SOLID nào không?", "Single responsibility: controller chỉ nhận request, service xử lý nghiệp vụ, StockService chỉ lo tồn kho. Dependency inversion: PaymentsService phụ thuộc interface charge() của gateway, inject qua DI của NestJS, nên thay MockPaymentGateway bằng cổng thật không phải sửa nghiệp vụ. Open/closed: thêm mã giảm giá mới chỉ thêm dữ liệu vào bảng promotions.", 2),
("Dependency Injection trong NestJS là gì?", "Container của NestJS tạo và cung cấp các provider (service) cho class cần dùng qua constructor, thay vì class tự new. Giúp dễ thay thế (mock trong test, đổi gateway) và giảm phụ thuộc cứng.", 2),
])

